    cin >> n;
    int *a = new int[n];            // массив из n int в динамической памяти
    for (int i = 0; i < n; i++)
    {
        cout << "Число " << i + 1 << ": -> ";
        cin >> a[i];
    }
    int s = 0;
    for (int i = 0; i < n; i++)
        s += a[i];
