#include <iostream.h>
#include <math.h>
#include <conio.h>

int main()
{
    double a, b, c, d, x1, x2;
    cout << "Введите a, b, c: -> ";
    cin >> a >> b >> c;
    if (a == 0)
    {
        if (b == 0)
            cout << "Это не уравнение" << endl;
        else
            cout << "Линейное, x = " << -c / b << endl;
    }
    else
    {
        d = b * b - 4 * a * c;
        if (d < 0)
            cout << "Действительных корней нет" << endl;
        else if (d == 0)
            cout << "Один корень x = " << -b / (2 * a) << endl;
        else
        {
            x1 = (-b + sqrt(d)) / (2 * a);
            x2 = (-b - sqrt(d)) / (2 * a);
            cout << "x1 = " << x1 << ", x2 = " << x2 << endl;
        }
    }
    getch();
    return 0;
}

#include <iostream.h>
