    cout << "Введите два числа: -> ";
    cin >> a >> b;
    cout << "Введите операцию (+ - * /): -> ";
    cin >> op;
    switch (op)
    {
        case '+': cout << a << " + " << b << " = " << a + b << endl; break;
        case '-': cout << a << " - " << b << " = " << a - b << endl; break;
        case '*': cout << a << " * " << b << " = " << a * b << endl; break;
        case '/':
            if (b == 0)
                cout << "Делить на ноль нельзя" << endl;
            else
                cout << a << " / " << b << " = " << a / b << endl;
            break;
        default:
            cout << "Неизвестная операция" << endl;
    }
    getch();
    return 0;
}

#include <iostream.h>
