int main()
{
    int y, m, d;
    cout << "Введите год и месяц: -> ";
    cin >> y >> m;
    bool leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    switch (m)
    {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            d = 31; break;
        case 4: case 6: case 9: case 11:
            d = 30; break;
        case 2:
            d = leap ? 29 : 28; break;
        default:
            d = 0;
    }
    if (d == 0)
        cout << "Такого месяца нет" << endl;
    else
        cout << "Дней в месяце: " << d << endl;
    getch();
    return 0;
}

