        s2 += a[i][n - 1 - i];                 // побочная диагональ
    }
    if (s2 != target) magic = false;
    for (i = 0; i < n; i++)
    {
        s = 0;
        for (j = 0; j < n; j++) s += a[i][j];  // строка i
        if (s != target) magic = false;
        s = 0;
        for (j = 0; j < n; j++) s += a[j][i];  // столбец i
        if (s != target) magic = false;
    }
    if (magic)
        cout << "Это магический квадрат, сумма = " << target << endl;
    else
        cout << "Это не магический квадрат" << endl;
