double power(double x, int n)
{
    if (n == 0) return 1;
    return x * power(x, n - 1);
}

long fact(int n)
{
    if (n <= 1) return 1;
    return n * fact(n - 1);
}

int sumTo(int n)
{
    if (n == 0) return 0;
    return n + sumTo(n - 1);
}

int main()
{
    double x;
    int n, m;
    cout << "Введите x и n (степень): -> ";
