    cout << x << " в степени " << n << " = " << power(x, n) << endl;
    cout << "Введите m: -> ";
    cin >> m;
    cout << m << "! = " << fact(m) << ", сумма 1.." << m << " = " << sumTo(m) << endl;
    getch();
    return 0;
}

