class Account
{
private:
    double balance;                        // состояние скрыто
public:
    Account(double start) { balance = start; }   // конструктор: начальное состояние
    double getBalance() { return balance; }
    void deposit(double sum)
    {
        if (sum > 0) balance += sum;
    }
    bool withdraw(double sum)
    {
        if (sum > 0 && sum <= balance)
        {
            balance -= sum;
            return true;
        }
        return false;                      // денег не хватает
    }
    bool transfer(Account &to, double sum) // взаимодействие двух объектов
    {
        if (withdraw(sum))
        {
            to.deposit(sum);
            return true;
        }
        return false;
    }
};

int main()
{
